local file = "Null_key.txt"
local OKkey = "null01"

local function loadKey()
    local success, savekey = pcall(function()
        return readfile(file)
    end)
    return success and savekey or ""
end

local function saveKey(key)
    pcall(function()
        writefile(file, key)
    end)
end

