local dragging = false
local dragInput
local dragStart
local startPos

local function updateDrag(input)
    local delta = input.Position - dragStart
    MainFrame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
end

MainFrame.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragging = true
        dragStart = input.Position
        startPos = MainFrame.Position
        
        input.Changed:Connect(function()
            if input.UserInputState == Enum.UserInputState.End then
                dragging = false
            end
        end)
    end
end)

MainFrame.InputChanged:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
        dragInput = input
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if input == dragInput and dragging then
        updateDrag(input)
    end
end)

local function applyButtonHoverEffect(button)
    button.MouseEnter:Connect(function()
        button.BackgroundTransparency = 0.4
    end)
    
    button.MouseLeave:Connect(function()
        button.BackgroundTransparency = 0.5
    end)
end

applyButtonHoverEffect(DiscordButton)

local function verifyAndExecuteKey(inputKey)
    if inputKey == "" then
        createNotification("Error", "Please input the key", 3, Color3.fromRGB(255, 85, 85), ScreenGui)
        StatusLabel.Text = "Status: Input Key"
        StatusLabel.TextColor3 = Color3.fromRGB(255, 85, 85)
        return false
    end
    
    if inputKey == OKkey then
        saveKey(OKkey)
        
        createNotification("Success", "Key is valid!", 5, Color3.fromRGB(85, 255, 127), ScreenGui)
        StatusLabel.Text = "Status: Valid Key!"
        StatusLabel.TextColor3 = Color3.fromRGB(85, 255, 127)
        
        task.delay(2, function()
            createNotification("Welcome", "Enjoy using the best touchline script", 3, Color3.fromRGB(255, 188, 254), ScreenGui)
            task.wait(1)
            ScreenGui:Destroy()
            --ATLAS SCRIPT HERE
            print("ATLAS SCRIPT LOADED")
        end)
        return true
    else
        createNotification("Error", "Wrong Key, please try again", 3, Color3.fromRGB(255, 85, 85), ScreenGui)
        StatusLabel.Text = "Status: Invalid Key"
        StatusLabel.TextColor3 = Color3.fromRGB(255, 85, 85)
        KeyTextbox.Text = ""
        return false
    end
end

